package main

import (
	"bufio"
	"fmt"
	"os"
)

func main() {
	reader := bufio.NewReader(os.Stdin)
	var n, m int
	fmt.Fscan(reader, &n, &m)
	ea := make([]int, m)
	eb := make([]int, m)
	for i := 0; i < m; i++ {
		fmt.Fscan(reader, &ea[i], &eb[i])
		ea[i]--
		eb[i]--
	}
	label := make([]int, n)
	best := 0
	total := 1
	for i := 0; i < n; i++ {
		total *= 6
	}
	for mask := 0; mask < total; mask++ {
		t := mask
		for i := 0; i < n; i++ {
			label[i] = t % 6
			t /= 6
		}
		var used [6][6]bool
		cnt := 0
		for i := 0; i < m; i++ {
			a := label[ea[i]]
			b := label[eb[i]]
			if a > b {
				a, b = b, a
			}
			if !used[a][b] {
				used[a][b] = true
				cnt++
			}
		}
		if cnt > best {
			best = cnt
		}
	}
	fmt.Println(best)
}
